from pathlib import Path
import sys
p=Path(sys.argv[1]);p.parent.mkdir(parents=True,exist_ok=True)
with p.open('x',encoding='utf-8',newline='') as o:o.write("diff --git a/src/cli/installer.ts b/src/cli/installer.ts\nindex c8e1233..49f9765 100644\n--- a/src/cli/installer.ts\n+++ b/src/cli/installer.ts\n@@ -1,7 +1,7 @@\n import { existsSync, readdirSync, readFileSync, writeFileSync } from 'fs';\n import { join, dirname, basename } from 'path';\n import { homedir, tmpdir } from 'os';\n-import { rm } from 'fs/promises';\n+import { mkdtemp, rm } from 'fs/promises';\n import * as p from '@clack/prompts';\n import { agents } from './agents.js';\n import type { Skill, InstallOptions } from './types.js';\n@@ -427,8 +427,13 @@ export async function installSkills(\n         .filter((d) => d.isDirectory() && !d.name.startsWith('.'))\n         .map((d) => d.name);\n \n-      const timestamp = new Date().toISOString().replace(/[:.]/g, '-');\n-      const trashDir = join(tmpdir(), `arra-oracle-skills-stale-${timestamp}`);\n+      // Allocate the recovery directory atomically instead of using a predictable\n+      // name in the shared system temp directory (which can be pre-created).\n+      let trashDir: string | undefined;\n+      const recoveryDir = async (): Promise<string> => {\n+        if (!trashDir) trashDir = await mkdtemp(join(tmpdir(), 'arra-oracle-skills-stale-'));\n+        return trashDir;\n+      };\n       let movedAny = false;\n       const failedMoves: string[] = [];\n \n@@ -438,11 +443,8 @@ export async function installSkills(\n         // Only cleanup if: 1) it's ours, 2) not in source anymore\n         if (await isOurSkill(installedPath) && !sourceSkillNames.includes(installed)) {\n           try {\n-            if (!movedAny) {\n-              await mkdirp(trashDir, shellMode);\n-              movedAny = true;\n-            }\n-            await mv(installedPath, join(trashDir, basename(installedPath)), shellMode);\n+            await mv(installedPath, join(await recoveryDir(), basename(installedPath)), shellMode);\n+            movedAny = true;\n             p.log.info(`Cleaned up orphan: ${installed} → ${trashDir}`);\n           } catch {\n             failedMoves.push(installedPath);\n@@ -452,7 +454,8 @@ export async function installSkills(\n           const pluginPath = join(homedir(), '.claude', 'plugins', installed);\n           if (existsSync(pluginPath) && await isOurSkill(pluginPath)) {\n             try {\n-              await mv(pluginPath, join(trashDir, basename(pluginPath)), shellMode);\n+              await mv(pluginPath, join(await recoveryDir(), basename(pluginPath)), shellMode);\n+              movedAny = true;\n             } catch {\n               failedMoves.push(pluginPath);\n             }\n")
